# -*- coding: utf-8 -*-
from odoo import models, fields, api

class AccountJournal(models.Model):
    _name = 'account.journal'
    _description = 'ACCOUNT JOURNAL'
    _order = 'id desc'

    activity_ids = fields.One2many(comodel_name="mail.activity", inverse_name='parent_id', string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    name = fields.Char(string="Journal Name", required=True)
    code = fields.Char(string="Short Code", required=True, help="Shorter name used for display. The journal entries of this journal will also be named using this prefix by default.")
    active = fields.Boolean(string="Active", help="Set active to false to hide the Journal without removing it.")
    type = fields.Selection(selection=[["sale","Sales"],["purchase","Purchase"],["cash","Cash"],["bank","Bank"],["general","Miscellaneous"]], string="Type", required=True, help="Select 'Sale' for customer invoices journals.\nSelect 'Purchase' for vendor bills journals.\nSelect 'Cash' or 'Bank' for journals that are used in customer or vendor payments.\nSelect 'General' for miscellaneous operations journals.")
    account_control_ids = fields.Many2many(comodel_name="account.account", string="Allowed accounts")
    default_account_type = fields.Char(string="Default Account Type", readonly=True)
    default_account_id = fields.Many2one(comodel_name="account.account", string="Default Account")
    suspense_account_id = fields.Many2one(comodel_name="account.account", string="Suspense Account", help="Bank statements transactions will be posted on the suspense account until the final reconciliation allowing finding the right account.")
    restrict_mode_hash_table = fields.Boolean(string="Lock Posted Entries with Hash", help="If ticked, the accounting entry or invoice receives a hash as soon as it is posted and cannot be modified anymore.")
    sequence = fields.Integer(string="Sequence", help="Used to order Journals in the dashboard view")
    invoice_reference_type = fields.Selection(selection=[["none","Open"],["partner","Based on Customer"],["invoice","Based on Invoice"]], string="Communication Type", required=True, help="You can set here the default communication that will appear on customer invoices, once validated, to help the customer to refer to that particular invoice when making the payment.")
    invoice_reference_model = fields.Selection(selection=[["odoo","Odoo"],["euro","European"]], string="Communication Standard", required=True, help="You can choose different models for each type of reference. The default one is the Odoo reference.")
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", help="The currency used to enter statement")
    company_id = fields.Many2one(comodel_name="res.company", string="Company", required=True, readonly=True, help="Company related to this journal")
    country_code = fields.Char(string="Country Code", readonly=True, help="The ISO country code in two chars. \nYou can use this field for quick search.")
    refund_sequence = fields.Boolean(string="Dedicated Credit Note Sequence", help="Check this box if you don't want to share the same sequence for invoices and credit notes made from this journal")
    payment_sequence = fields.Boolean(string="Dedicated Payment Sequence", help="Check this box if you don't want to share the same sequence on payments and bank transactions posted on this journal")
    sequence_override_regex = fields.Text(string="Sequence Override Regex", help="Technical field used to enforce complex sequence composition that the system would normally misunderstand.\nThis is a regex that can include all the following capture groups: prefix1, year, prefix2, month, prefix3, seq, suffix.\nThe prefix* groups are the separators between the year, month and the actual increasing sequence number (seq).\ne.g: ^(?P<prefix1>.*?)(?P<year>\\d{4})(?P<prefix2>\\D*?)(?P<month>\\d{2})(?P<prefix3>\\D+?)(?P<seq>\\d+)(?P<suffix>\\D*?)$")
    inbound_payment_method_line_ids = fields.One2many(comodel_name="account.payment.method.line", inverse_name='parent_id', string="Inbound Payment Methods", help="Manual: Get paid by any method outside of Odoo.\nPayment Providers: Each payment provider has its own Payment Method. Request a transaction on/to a card thanks to a payment token saved by the partner when buying or subscribing online.\nBatch Deposit: Collect several customer checks at once generating and submitting a batch deposit to your bank. Module account_batch_payment is necessary.\nSEPA Direct Debit: Get paid in the SEPA zone thanks to a mandate your partner will have granted to you. Module account_sepa is necessary.\n")
    outbound_payment_method_line_ids = fields.One2many(comodel_name="account.payment.method.line", inverse_name='parent_id', string="Outbound Payment Methods", help="Manual: Pay by any method outside of Odoo.\nCheck: Pay bills by check and print it from Odoo.\nSEPA Credit Transfer: Pay in the SEPA zone by submitting a SEPA Credit Transfer file to your bank. Module account_sepa is necessary.\n")
    profit_account_id = fields.Many2one(comodel_name="account.account", string="Profit Account", help="Used to register a profit when the ending balance of a cash register differs from what the system computes")
    loss_account_id = fields.Many2one(comodel_name="account.account", string="Loss Account", help="Used to register a loss when the ending balance of a cash register differs from what the system computes")
    company_partner_id = fields.Many2one(comodel_name="res.partner", string="Account Holder", readonly=True)
    bank_account_id = fields.Many2one(comodel_name="res.partner.bank", string="Bank Account")
    bank_statements_source = fields.Selection(selection=[["undefined","Chưa xác định"]], string="Bank Feeds", help="Defines how the bank statements will be registered")
    bank_acc_number = fields.Char(string="Account Number")
    bank_id = fields.Many2one(comodel_name="res.bank", string="Bank")
    sale_activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Schedule Activity", help="Activity will be automatically scheduled on payment due date, improving collection process.")
    sale_activity_user_id = fields.Many2one(comodel_name="res.users", string="Activity User", help="Leave empty to assign the Salesperson of the invoice.")
    sale_activity_note = fields.Text(string="Activity Summary")
    alias_id = fields.Many2one(comodel_name="mail.alias", string="Email Alias", help="Send one separate email for each invoice.\n\nAny file extension will be accepted.\n\nOnly PDF and XML files will be interpreted by Odoo")
    alias_domain = fields.Char(string="Alias domain", readonly=True)
    alias_name = fields.Char(string="Alias Name", help="It creates draft invoices and bills by sending an email.")
    journal_group_ids = fields.Many2many(comodel_name="account.journal.group", string="Journal Groups")
    secure_sequence_id = fields.Many2one(comodel_name="ir.sequence", string="Secure Sequence", readonly=True, help="Sequence to use to ensure the securisation of data")
    available_payment_method_ids = fields.Many2many(comodel_name="account.payment.method", string="Available Payment Method", readonly=True)
    selected_payment_method_codes = fields.Char(string="Selected Payment Method Codes", readonly=True)
    kanban_dashboard = fields.Text(string="Kanban Dashboard", readonly=True)
    kanban_dashboard_graph = fields.Text(string="Kanban Dashboard Graph", readonly=True)
    json_activity_data = fields.Text(string="Json Activity Data", readonly=True)
    show_on_dashboard = fields.Boolean(string="Show journal on dashboard", help="Whether this journal should be displayed on the dashboard or not")
    color = fields.Integer(string="Color Index")
    current_statement_balance = fields.Monetary(string="Current Statement Balance", readonly=True)
    has_statement_lines = fields.Boolean(string="Has Statement Lines", readonly=True)
    entries_count = fields.Integer(string="Entries Count", readonly=True)
    has_sequence_holes = fields.Boolean(string="Has Sequence Holes", readonly=True)
    edi_format_ids = fields.Many2many(comodel_name="account.edi.format", string="Electronic invoicing", help="Send XML/EDI invoices")
    compatible_edi_ids = fields.Many2many(comodel_name="account.edi.format", string="Compatible Edi", readonly=True, help="EDI format that support moves in this journal")
    reconcile_mode = fields.Selection(selection=[["edit","Edit Move"],["keep","Keep Suspense Accounts"]], string="Reconcile Mode", required=True)
    company_currency_id = fields.Many2one(comodel_name="res.currency", string="Company Currency", readonly=True)
    reconcile_aggregate = fields.Selection(selection=[["statement","Statement"],["day","Day"],["week","Week"],["month","Month"]], string="Reconcile aggregation", help="Aggregation to use on reconcile view")
    einvoice_enable = fields.Boolean(string="E-Invoice Enable")
    einvoice_serial_id = fields.Many2one(comodel_name="einvoice.serial", string="Einvoice Serial")
    einvoice_template_id = fields.Many2one(comodel_name="einvoice.template", string="E-Invoice Template", readonly=True)
    einvoice_type_id = fields.Many2one(comodel_name="einvoice.type", string="E-Invoice Type", readonly=True)
    einvoice_provider_id = fields.Many2one(comodel_name="einvoice.provider", string="E-Invoice Provider", readonly=True)
    einvoice_send_mail_option = fields.Selection(selection=[["display","Display Version"],["converted","Converted Version"]], string="E-Invoice Send Mail/Portal option", help="Choose which version of E-Invoice will be available for mail sending and download and print from customer portal.")
    is_advance_journal = fields.Boolean(string="Employee Advance Journal?", help="Check this to enable this journal for employee advance.")
